// scan.Mapper[*T] without reflection: maps columns to fields by index.
func animalScanMapper(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Animal, error)) {
	// resolve the column positions once per query, not per row
	type target struct {
		idx int
		dst func(o *Animal) any
	}
	targets := make([]target, 0, 22)
	for i, col := range cols {
		switch col {
		case "id":
			targets = append(targets, target{i, func(o *Animal) any { return &o.ID }})
		case "user_id":
			targets = append(targets, target{i, func(o *Animal) any { return &o.UserID }})
		case "organization_id":
			targets = append(targets, target{i, func(o *Animal) any { return &o.OrganizationID }})
		case "type_id":
			targets = append(targets, target{i, func(o *Animal) any { return &o.TypeID }})
		case "specie_id":
			targets = append(targets, target{i, func(o *Animal) any { return &o.SpecieID }})
		case "name":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Name }})
		case "gender":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Gender }})
		case "hermaphrodite":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Hermaphrodite }})
		case "age":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Age }})
		case "size":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Size }})
		case "image_object_kind":
			targets = append(targets, target{i, func(o *Animal) any { return &o.ImageObjectKind }})
		case "image_object_ref_small":
			targets = append(targets, target{i, func(o *Animal) any { return &o.ImageObjectRefSmall }})
		case "image_object_ref_medium":
			targets = append(targets, target{i, func(o *Animal) any { return &o.ImageObjectRefMedium }})
		case "image_object_ref_large":
			targets = append(targets, target{i, func(o *Animal) any { return &o.ImageObjectRefLarge }})
		case "image_object_ref_full":
			targets = append(targets, target{i, func(o *Animal) any { return &o.ImageObjectRefFull }})
		case "description":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Description }})
		case "distance":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Distance }})
		case "properties":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Properties }})
		case "status":
			targets = append(targets, target{i, func(o *Animal) any { return &o.Status }})
		case "original_organization_id":
			targets = append(targets, target{i, func(o *Animal) any { return &o.OriginalOrganizationID }})
		case "created_at":
			targets = append(targets, target{i, func(o *Animal) any { return &o.CreatedAt }})
		case "updated_at":
			targets = append(targets, target{i, func(o *Animal) any { return &o.UpdatedAt }})
		}
	}

	return func(row *scan.Row) (any, error) {
			o := new(Animal)
			for _, t := range targets {
				row.ScheduleScanByIndex(t.idx, t.dst(o))
			}
			return o, nil
		}, func(v any) (*Animal, error) {
			return v.(*Animal), nil
		}
}

// FindAnimal retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindAnimal(ctx context.Context, exec bob.Executor, IDPK int64, cols ...string) (*Animal, error) {
	if len(cols) == 0 {
		return Animals.Query(
			sm.Where(Animals.Columns.ID.EQ(psql.Arg(IDPK))),
		).One(ctx, exec)
	}

	return Animals.Query(
		sm.Where(Animals.Columns.ID.EQ(psql.Arg(IDPK))),
		sm.Columns(Animals.Columns.Only(cols...)),
	).One(ctx, exec)
}

