// AfterQueryHook is called after Animal is retrieved from the database
func (o *Animal) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Animals.AfterSelectHooks.RunHooks(ctx, exec, AnimalSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = Animals.AfterInsertHooks.RunHooks(ctx, exec, AnimalSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = Animals.AfterUpdateHooks.RunHooks(ctx, exec, AnimalSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = Animals.AfterDeleteHooks.RunHooks(ctx, exec, AnimalSlice{o})
	case bob.QueryTypeMerge:
		ctx, err = Animals.AfterMergeHooks.RunHooks(ctx, exec, AnimalSlice{o})
	}

	return err
}

// primaryKeyVals returns the primary key values of the Animal
func (o *Animal) primaryKeyVals() bob.Expression {
	return psql.Arg(o.ID)
}

func (o *Animal) pkEQ() dialect.Expression {
	return psql.Quote("animal", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the Animal
func (o *Animal) Update(ctx context.Context, exec bob.Executor, s *AnimalSetter) error {
	v, err := Animals.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

// Delete deletes a single Animal record with an executor
func (o *Animal) Delete(ctx context.Context, exec bob.Executor) error {
	_, err := Animals.Delete(dm.Where(o.pkEQ())).Exec(ctx, exec)
	return err
}

// Reload refreshes the Animal using the executor
func (o *Animal) Reload(ctx context.Context, exec bob.Executor) error {
	o2, err := Animals.Query(
		sm.Where(Animals.Columns.ID.EQ(psql.Arg(o.ID))),
	).One(ctx, exec)
	if err != nil {
		return err
	}
	o2.R = o.R
	*o = *o2

	return nil
}

// AfterQueryHook is called after AnimalSlice is retrieved from the database
func (o AnimalSlice) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Animals.AfterSelectHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeInsert:
		ctx, err = Animals.AfterInsertHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeUpdate:
		ctx, err = Animals.AfterUpdateHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeDelete:
		ctx, err = Animals.AfterDeleteHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeMerge:
		ctx, err = Animals.AfterMergeHooks.RunHooks(ctx, exec, o)
	}

	return err
}

func (o AnimalSlice) pkIN() dialect.Expression {
	if len(o) == 0 {
		return psql.Raw("NULL")
	}

	return psql.Quote("animal", "id").In(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		pkPairs := make([]bob.Expression, len(o))
		for i, row := range o {
			pkPairs[i] = row.primaryKeyVals()
		}
		return bob.ExpressSlice(ctx, w, d, start, pkPairs, "", ", ", "")
	}))
}

// copyMatchingRows finds models in the given slice that have the same primary key
// then it first copies the existing relationships from the old model to the new model
// and then replaces the old model in the slice with the new model
func (o AnimalSlice) copyMatchingRows(from ...*Animal) {
	fromByPK := make(map[int64]*Animal, len(from))
	for _, new := range from {
		// keep the first row for each key, like the nested loop did
		if _, ok := fromByPK[new.ID]; !ok {
			fromByPK[new.ID] = new
		}
	}

	for i, old := range o {
		new, ok := fromByPK[old.ID]
		if !ok {
			continue
		}
		new.R = old.R
		o[i] = new
	}
}

// UpdateMod modifies an update query with "WHERE primary_key IN (o...)"
func (o AnimalSlice) UpdateMod() bob.Mod[*dialect.UpdateQuery] {
	return bob.ModFunc[*dialect.UpdateQuery](func(q *dialect.UpdateQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Animals.BeforeUpdateHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Animal:
				o.copyMatchingRows(retrieved)
			case []*Animal:
				o.copyMatchingRows(retrieved...)
			case AnimalSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Animal or a slice of Animal
				// then run the AfterUpdateHooks on the slice
				_, err = Animals.AfterUpdateHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// DeleteMod modifies an delete query with "WHERE primary_key IN (o...)"
func (o AnimalSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Animals.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Animal:
				o.copyMatchingRows(retrieved)
			case []*Animal:
				o.copyMatchingRows(retrieved...)
			case AnimalSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Animal or a slice of Animal
				// then run the AfterDeleteHooks on the slice
				_, err = Animals.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// MergeMod modifies a merge query to run BeforeMergeHooks and AfterMergeHooks
// and updates the slice with the returned rows.
func (o AnimalSlice) MergeMod() bob.Mod[*dialect.MergeQuery] {
	return bob.ModFunc[*dialect.MergeQuery](func(q *dialect.MergeQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Animals.BeforeMergeHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Animal:
				o.copyMatchingRows(retrieved)
			case []*Animal:
				o.copyMatchingRows(retrieved...)
			case AnimalSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Animal or a slice of Animal
				// then run the AfterMergeHooks on the slice
				_, err = Animals.AfterMergeHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))
	})
}

func (o AnimalSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals AnimalSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Animals.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o AnimalSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Animals.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o AnimalSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := Animals.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

